"""Render results/existing_audio_inventory.md from results/existing_audio_inventory.json (numbers only; no new analysis)."""
import json

d = json.load(open("results/existing_audio_inventory.json", encoding="utf-8"))
F = d["files"]


def mm(s):
    return f"{s / 60:.1f}"


L = [
    "# Existing audio inventory (7 files)", "",
    "Phase 1 of the existing-audio evaluation. Source: `C:\\Users\\sriha\\snypar\\stt\\data` (originals untouched, read-only, sha256 in the manifest). "
    "Generated by `benchmarks/inventory_existing.py` -> `results/existing_audio_inventory.json`. Labels: MEASURED = computed from the audio; "
    "OBSERVED = read from the numbers, cause unverified; UNKNOWN = not determinable from current data. "
    "**Nobody listened to the audio and no transcript exists**, so nothing below is verified by ear.", "",
    f"**Total decoded duration: {d['total_min']} min ({d['total_min'] / 60:.2f} h)** over {len(F)} files, "
    f"{sum(f['file_bytes'] for f in F) / 1e6:.0f} MB.", "",
    "All levels are on the 16 kHz mono PCM16 working decode (full scale 1.0). Native files are lossy, so bit depth is n/a.", "",
    "## 1. Container, format, size (MEASURED)", "",
    "| id | filename | codec (container) | native rate | ch | kbps | min | MB | bit depth |",
    "|---|---|---|---|---|---|---|---|---|",
]
for f in F:
    L.append(f"| {f['recording_id']} | {f['source_filename']} | {f['codec']} ({f['container']}) | {f['native_rate']} | "
             f"{f['native_channels']} | {(f['bit_rate'] or 0) / 1000:.0f} | {mm(f['decoded_duration_s'])} | {f['file_bytes'] / 1e6:.1f} | n/a (lossy) |")
L += ["",
      "- rec01-rec04 carry a `.mp3` extension but hold Opus at 48 kHz stereo (encoder tag `google/video-file`; OBSERVED: probably audio extracted from video). "
      "rec05-rec07 are real MP3 at 44.1 kHz stereo with YouTube-style title/channel tags.",
      "- Stereo downmix is a plain mean. Inter-channel correlation was not analysed.", "",
      "## 2. Levels and quality (MEASURED)", "",
      "| id | peak dBFS | RMS overall | RMS p95 | RMS median | floor (p10) | est. SNR dB | samples >= 0.999 | frames >= 0.01 | quiet share of voiced (0.01-0.03) |",
      "|---|---|---|---|---|---|---|---|---|---|"]
for f in F:
    L.append(f"| {f['recording_id']} | {f['peak_dbfs']} | {f['rms_overall']} | {f['rms_p95']} | {f['rms_median']} | {f['rms_p10_floor']} | "
             f"{f['est_snr_db']} | {f['clipped_samples_ge_0p999']} ({f['clipped_pct']}%) | {f['voiced_frac_fixed_thr']*100:.0f}% | {f['quiet_voiced_frac']*100:.0f}% |")
L += ["", "Est. SNR = 20 log10(p95 frame RMS / p10 frame RMS): a crude speech-to-floor ratio, not a true SNR.", "",
      "## 3. Noise-floor character, quietest 5% of frames (MEASURED)", "",
      "| id | energy < 300 Hz | energy > 4 kHz | spectral centroid Hz | 45-65 Hz share |", "|---|---|---|---|---|"]
for f in F:
    n = f["noise_floor_character"]
    L.append(f"| {f['recording_id']} | {n.get('frac_energy_below_300hz')} | {n.get('frac_energy_above_4khz')} | {n.get('spectral_centroid_hz')} | {n.get('hum_50_60hz_frac')} |")
L += ["", "High sub-300 Hz share means rumble/room tone; high >4 kHz share means hiss-like floor. Hum is not established (45-65 Hz share is small).", "",
      "## 4. Pauses (MEASURED as energy gaps; not speech annotation)", "",
      "Pause = run of 20 ms frames below a threshold, excluding leading/trailing silence. Two thresholds: the production fixed 0.01, and 35 dB below the file's speech level. "
      "They disagree strongly when the floor is not far below 0.01.", "",
      "| id | threshold | pauses | pause time share | median s | longest s | 0.1-0.3 | 0.3-0.6 | 0.6-1.2 | 1.2-3 | >=3 s | >=0.6 s |",
      "|---|---|---|---|---|---|---|---|---|---|---|---|"]
for f in F:
    for k, nm in (("pauses_fixed_0p01", "fixed"), ("pauses_rel_minus35db", "rel -35 dB")):
        p = f[k]
        h = p["hist"]
        L.append(f"| {f['recording_id']} | {nm} ({p['thr']}) | {p['n_pauses']} | {p['pause_fraction']*100:.0f}% | {p['median_pause_s']} | {p['longest_pause_s']} | "
                 f"{h['0.1-0.3s']['n']} | {h['0.3-0.6s']['n']} | {h['0.6-1.2s']['n']} | {h['1.2-3s']['n']} | {h['>=3s']['n']} | {p['n_ge_0p6']} |")
L += ["", "## 5. Per-file observations (OBSERVED; causes unverified)", "",
      "- **rec01**: quietest. Few frames reach the production 0.01 threshold; most voiced frames sit in the 0.01-0.03 band. Candidate for quiet-speech under-trigger behaviour. Fixed-threshold pause count is inflated by low-level speech.",
      "- **rec02**: healthy level, floor well below 0.01. Fixed-threshold pauses far exceed relative-threshold pauses, so many 'pauses' are low-level speech or room tone.",
      "- **rec03**: broadband, hiss-like floor (see section 3). Peak at 0 dBFS; check clipped-sample column for real clipping.",
      "- **rec04**: highest floor of the lectures and densest speech. Nearly no relative-threshold pauses of 0.6 s or more versus hundreds at the fixed threshold: continuous talk over an audible floor, or noise-filled gaps.",
      "- **rec05**: floor (p10 RMS) already above the production 0.01 threshold; no sub-threshold run of 0.6 s or more. Under the fixed VAD it will rarely see a silence flush and will rely on the 8 s cap. Dense or edited speech, background audio, or both; unverified. Interview-style title suggests several speakers (unverified).",
      "- **rec06**: normal level, natural pauses, one clipped sample.",
      "- **rec07**: only file with notable clipping (see section 2); still a tiny fraction of samples. Natural pauses.", "",
      "## 6. Speakers, continuity, noise", "",
      "| question | status | evidence |", "|---|---|---|",
      "| Distinct speakers per file | **UNKNOWN** | No diarization, annotation or metadata. 7 files is not 7 speakers. No speaker IDs created |",
      "| Single vs multiple speakers | **UNKNOWN** | Filename/tag hints only (lecture-style rec01-03, interview-style rec05, single-creator rec06/07); unverified |",
      "| Continuous vs edited | **OBSERVED, partial** | rec05 has no gap >= 0.6 s in 8.8 min. Others show natural-looking pause distributions. No jump-cut detection run |",
      "| Natural pauses | **MEASURED** | Present rec01-04, 06, 07 (section 4); effectively absent rec05 |",
      "| Quiet speech | **MEASURED** | rec01 clearly; see quiet-share column for others |",
      "| Background noise | **OBSERVED** | Floor levels in section 2; type (music, room, babble) not identified |",
      "| Language / accent | **USER-STATED** | Indian English per task statement; not verified per file |", "",
      "## 7. Limits",
      "- Lossy decode and resample shift levels slightly versus originals; peak and clipping figures are on the decode.",
      "- Energy-based pause counts are not speech annotation; they give no speech recall or false activation.",
      "- Speaker count, content and transcripts need a human; none supplied.", ""]
open("results/existing_audio_inventory.md", "w", encoding="utf-8").write("\n".join(L))
print("ok")
